from math import ceil

from models import fmt, pct, rub


def unit(v, detail):
    price, cost, fee, other, units, delta = v
    arr = [price, cost, fee, other]
    arr[{"price":0,"cost":1,"fee":2,"other":3}[detail]] += delta
    net = arr[0] - sum(arr[1:])
    goal = max(0, net // 5)
    baseline = price - cost - fee - other
    extra_value = net * max(0, units - 10)
    return (
        f"Допустим, после изменений селлер хочет оставить запас на неожиданный расход хотя бы {rub(goal)} с единицы. При новых начислениях и себестоимости для этого нужна чистая цена от {rub(sum(arr[1:]) + goal)} при прочих неизменных суммах. Здесь мы выбрали пятую часть нового вклада как учебное ограничение, его можно заменить своей суммой. Та же логика помогает сравнить две скидки или два предложения поставщика. Если минимальный вклад рассчитан на покрытие общих расходов, проверьте, что в месячном бюджете они добавлены только один раз. При фиксированных расходах сниженный объём может потребовать большего запаса на единицу.",
        f"Проверьте неопределённость с другой стороны. Если вместо {units} будет на десять доставленных единиц меньше, при новом вкладе результат составит {rub(extra_value)}. Разница с ориентиром для исходного объёма равна {rub(net * units - extra_value)}. Если десять продаж, наоборот, добавятся к плану, вклад составит {rub(net*(units+10))}. Эти варианты предполагают, что на удельные затраты новая нагрузка не влияет. В своём файле отметьте, когда нужен дополнительный рейс, упаковка другого размера или платная смена. Тогда переход от {units} к {units+10} может менять сразу и объём, и расходы.",
        f"Для разбора отклонения лучше хранить рабочий артикул, журнал цен и связанные расходы в одном диапазоне дат. Начните с результата {rub(baseline)} на единицу и проведите два подсчёта: один по обычным условиям, другой по изменённым. Если фактическая чистая цена стала ниже ожидаемой, в первом изменённом сценарии сохраните прежний расход и замените только цену. Во втором добавьте факт расходов. Такой порядок позволяет не записать всё отклонение в изменение закупки. Если часть партий продаётся одновременно, для проверки сохраняйте связь с партией или явно укажите, каким методом считали себестоимость. Обновите договорённость о цене после первых сопоставимых завершённых продаж."
    )


def investment(v, item):
    fixed, prev, new, runs = v
    gain=prev-new
    period=ceil(fixed/(gain*runs))
    cap=max(0, prev-fixed/runs)
    return (
        f"Для планирования бюджета удобно перейти от количества к периодам. При {runs} операциях за период переменная экономия равна {rub(gain*runs)}. Если объём повторяется, разовая трата {rub(fixed)} будет покрыта к концу {period}-го полного периода. После двух таких периодов условный результат составит {rub(2*gain*runs-fixed)}. Расчёт предполагает, что объём не падает и новую цену удаётся сохранить. Если устройство выйдет из строя или подрядчик временно перестанет принимать заказы, поставьте на шкалу даты, с которых экономия действительно действует. Тогда окупаемость можно проверить после закупки, даже если запуск занял несколько недель.",
        f"Второй способ сформулировать цель теста: каким может быть расход нового способа при {runs} обработанных единицах, если проект должен закрыть разовый бюджет за первый период? При старых {rub(prev)} верхняя граница нового переменного расхода составляет {rub(cap,2)}, если она положительна. Если закупка уже дороже всего старого процесса за период, даже бесплатная операция не окупит переход за этот срок. В этом случае меняем горизонт контроля или уменьшаем стартовый бюджет. Не принимайте оценку за тариф: подставьте материалы, фактический расчёт оплаты и ассортимент задач, которые действительно можно перенести.",
        f"Предусмотрите выборку для рабочей единицы «{item}» в двух сменах с различной загрузкой. Первая проверка сравнивает простой поток, вторая берёт ту часть, где есть повторная операция, ручная корректировка или ожидание. В обоих случаях одинаково фиксируйте начало, окончание и расход материалов. Если времени стало меньше, а денежный эффект не подтвердился, в записях остаётся отдельный выигрыш по времени, который можно направить на следующий участок. Если после внедрения не нужно тратить часть старых {rub(prev)} на обслуживание, подтвердите это по обычной закупке следующего периода. Так вывод про экономику не подменяет наблюдение про комфорт сотрудников."
    )


def quality(v, reason):
    n, x, y, fee, fixed=v
    rate=x/n
    cost_rate=ceil(fixed/fee)/n
    estimate = max(0, x - ceil(fixed/fee))
    return (
        f"Из оценки можно получить ориентир для смены. Чтобы покрыть пробные затраты при {n} операциях, нужна разница не меньше {pct(cost_rate,2)} по доле подтверждённых случаев. При исходных {x} случаях наблюдение в новой группе должно дать не больше {estimate}, если экономия происходит только за счёт этой причины. Если разовая мера влияет на несколько причин, разбейте снижение по ним. Пусть считаете итог по деньгам: ни одну повторную доставку не включаем дважды, даже если ошибка отразилась в двух журналах. Для команды важны все подтверждённые случаи, а для сметы учитываются конкретные дополнительные расходы.",
        f"Посчитайте текущий прямой расход на 100 операций: при исходном отношении {pct(rate,2)} это {rub(rate * 100 * fee,2)}. В пилоте на тех же 100 условно получилось бы {rub(y/n*100*fee,2)} без учёта запуска. Разделение удобно, если за неделю смена провела другой объём. Когда новый поток состоит из других товарных групп, сначала пересчитайте старое отношение на их сопоставимых участках. Если ошибка «{reason}» относится только к двум соседним ячейкам, общий процент может улучшиться за счёт того, что этими ячейками пользовались реже. Сохраняйте объём именно этой группы отдельно.",
        f"Для проверки после вмешательства полезно вести три состояния: замечено внутренним контролем, подтверждено после следующего этапа, причину не удалось установить. Это помогает понять, что именно изменилось. Если стали находить больше до отправки, число подтверждённых внешних случаев может уменьшиться даже при той же частоте первоначальной ошибки. Если задача состоит в профилактике, на следующем цикле сравните обе части, а не только выплаты. Для финансовой аналитики «{reason}» знак успешного изменения должен сопровождаться подтверждённым расходом или обоснованным его отсутствием. В противном случае оставьте строку оценки, пока не появились итоговые начисления."
    )


def cash(v, name):
    start, incoming, first, second, reserve = v
    after = start-first-second
    thirds = (incoming//3, incoming*2//3, incoming)
    outcome = " / ".join(rub(after+t) for t in thirds)
    return (
        f"Перед расходом «{name}» можно посчитать три варианта ближайшего поступления: треть, две трети и вся ожидаемая сумма {rub(incoming)}. После оплаты доступный остаток приблизительно {outcome}. Это полезно в день, когда часть подтверждений уже появилась, но остальные ещё под вопросом. Для рабочего решения отмечайте суммы, которые действительно стали доступны магазину. Если остаток после любого неполного варианта заметно ниже {rub(reserve)}, по этой расходной строке нужна договорённость о переносе. Порог резерва следует соотнести с обязательными тратами следующего дня, иначе удобная круглая сумма может не помочь.",
        f"Добавьте проверку на непредвиденный расход. Пусть до подтверждённого поступления магазин потратил ещё десятую часть первого счёта, то есть {rub(first//10)}. Сразу после второго платежа останется {rub(after-first//10)}, если поступление переносится. При своевременном полном поступлении ожидаем {rub(after+incoming-first//10)}. Эти варианты показывают очередность риска. Если один поставщик готов разделить счёт, рассчитайте, какую долю реально можно заплатить сейчас, а для второй части выберите подтверждённую календарную дату. Сохраните переписку или счёт, чтобы не принять желаемый график за согласованный.",
        f"Рабочий контроль для «{name}» можно устроить без пересчёта всех продаж. Сверьте доступную сумму на счёте и список платежей, срок которых наступает до следующего ожидаемого зачисления. Затем проверьте, какие суммы фактически удерживаются из выплаты и уже включены в ожидаемые {rub(incoming)}. Если их отразить как независимые списания, разрыв получится больше реального. В отчёте после закрытия сравните прогноз даты зачисления с выпиской и укажите, было ли в этот момент важное обязательство. Отдельно договоритесь, кто обновляет лист при изменении статуса, поскольку результат может сдвинуться за несколько часов."
    )


def stock(v, product):
    available, daily, lead, reserve, lot =v
    forecast=available/daily
    slow=max(1,daily-1)
    fast=daily+1
    return (
        f"Чтобы поставить напоминание, запишите доступное покрытие по позиции «{product}». При обычном расходе {daily} единиц в день запас {available} даёт около {fmt(forecast,1)} дня. При {slow} единицах выйдет {fmt(available/slow,1)}, при {fast} около {fmt(available/fast,1)} дня. Эти числа усредняют расход, поэтому на календаре отдельно выделите день крупных отгрузок и день, когда поставщик действительно принимает заявку. Если отгрузки на начало недели выше, можно перенести часть недельного объёма в первые два дня и увидеть, на какой срок падает покрытие. Это точнее, чем ждать дробную величину дня как календарный срок.",
        f"Если пришла лишь половина партии {lot}, в простой модели это {lot//2} пригодных единиц нового запаса. При {lead} днях ожидания и расходе {daily} прогнозируемый запас после фактического приёма составит {max(0,available-daily*lead) + lot//2} при условии отсутствия переносимых заказов. Для товара, который уже пообещали покупателям или зарезервировали на другом канале, уменьшите доступный результат. С поставщиком уточните, можно ли делить поставку и не изменится ли минимальная партия. Если второй приход только предполагается, оставьте его как отдельный сценарий, а не объявляйте текущим доступным объёмом.",
        f"К следующему циклу подготовьте простой календарь изменения остатка: прогноз свободного количества утром, подтверждённый расход вечером, факт прихода и количество пригодных единиц после осмотра. Пример с «{product}» предполагает, что запас выделен для одного потока. Если он общий, внесите изъятия для каждого канала и проверьте, в какие дни накладываются крупные продажи. В конце срока сравните остаток не только с нулём, но и с исходным резервом {reserve}. Когда товар регулярно подходит к нему уже через пару дней, пересмотрите срок поставки, начальный запас или текущий темп. Для дорогих позиций добавьте рядом стоимость дополнительного запаса, чтобы рост резерва был виден в деньгах."
    )


SUPPLEMENTS = {"01":unit,"02":investment,"03":quality,"04":cash,"05":stock}


def mix(v, unit):
    stock, a_use, b_use, a_net, b_net=v
    a_count,b_count=stock//a_use,stock//b_use
    b_at_five=min(5,b_count)
    a_after=(stock-b_at_five*b_use)//a_use
    return (
        f"Сравните два крайних плана, прежде чем распределять «{unit}». Если всё отдаём под А, можно собрать {a_count} целых изделий с потенциальным вкладом {rub(a_count*a_net)}. Если всё отдаём под Б, получаем {b_count} и {rub(b_count*b_net)}. Разница в остатке {stock % a_use} против {stock % b_use} поможет оценить, какой материал останется в работе. Если остаток пригодится уже в следующей закупке, не записывайте его в потери. Если он подходит только к уходящей модели, отдельная строка с его применением полезнее одного общего числа. Реальные ограничения на спрос добавляйте до расчёта вклада периода.",
        f"Для небольшой проверки зарезервируйте под Б не больше {b_at_five} продаж. При том же запасе остаётся ресурс для {a_after} продаж А, если их смогут исполнить. Вклад такого сочетания {rub(b_at_five*b_net+a_after*a_net)}. Сравните его с расчётом только А. Затем посмотрите, какой расход поменяется при одновременной сборке. Возможно, понадобится отдельная коробка для пяти комплектов, которую нельзя купить ровно в нужном количестве. Тогда добавьте фактический расход сценария или сохраните остаток упаковки как отдельную цифру. За день до сборки перепроверьте, какие покупатели уже ждут доставку каждого варианта.",
        f"При переносе таблицы склада помечайте, когда ресурс «{unit}» закончился у каждого предложения. Если готовый товар в запасе есть, а отдельные детали уже зарезервированы для его выпуска, избыток в учётном файле может быть просто повтором. Проверьте один комплект по списку материалов и сопоставьте фактический расход с {a_use} и {b_use}. Для подходящей серии обновляйте исходный остаток после списаний, пока есть продажи из двух каналов. После подтверждения спроса переносите часть плана, сверяя не только количество коробок, но и вклад каждой реально доставленной единицы."
    )


def report(v, record):
    rows, missing, doubled, total, cost_missing, cost_double=v
    gain=missing*cost_missing
    loss=doubled*cost_double
    return (
        f"Посчитайте отдельно доли двух ошибок. Подтверждённые пропуски составляют {pct(missing/(rows+missing-doubled),2)} от проверенного числа строк, дубли {pct(doubled/rows,2)} от первоначальной сводной. В единицах денег это {rub(gain)} для добавлений и {rub(loss)} для дублей. Проценты имеют разные знаменатели, поэтому в таблице указывайте группы полностью. Малая чистая разница иногда получается потому, что большие движения почти компенсировали друг друга. При стабильной сумме за месяц имеет смысл проверить выборку строк, чтобы выявить неправильную принадлежность конкретному артикулу. На товарном уровне эти ошибки могут уходить в разные стороны.",
        f"Проверьте, как повлияла бы одна спорная запись «{record}». Если её ошибочно приняли за пропуск, итог изменился бы на {rub(cost_missing)}. Если лишнюю запись оставили до выяснения, результат был бы выше на {rub(cost_double)}. В рабочем отчёте заведите колонку с датой подтверждения и порогом суммы, после которого спорную операцию проверят первой. Не заменяйте знак расхода знаком поступления при импорте. Если фактические записи объединяют несколько позиций, разбейте их только там, где источник даёт однозначную связь. Иначе в отчёте оставьте сумму без распределения до сверки.",
        f"Завершать импорт удобно небольшой пробой на уже проверенном периоде. При повторной загрузке одного файла число уникальных операций и итог {rub(total+gain-loss)} должны сохраниться, если данные не изменились. Если в файле изменился статус, сравните исходное событие и обновлённую строку по идентификатору. Если изменилось лишь представление даты, проверьте, что вспомогательная колонка не создаёт вторую операцию. Для «{record}» полезно отдельно указать допустимые причины разницы между оригиналом и копией. Так следующая рабочая версия будет воспроизводиться из исходника и журнала исправлений."
    )


def route(v, route_name):
    boxes, trips, ticket, unit, fixed=v
    typical=boxes/trips
    next_cost=(trips+1)*ticket
    return (
        f"Из {boxes} коробок и {trips} поездок получается примерно {fmt(typical,1)} коробки на рейс. Это среднее не подтверждает вместимость: один выезд может увезти два крупногабаритных места, другой десять маленьких. Для сравнения «{route_name}» начните с фактического числа и вида мест в каждом рейсе. Добавьте строку на остановки у разных пунктов, если по ним есть доплата. Только после этого решайте, сохранится ли прежний график при увеличении объёма. Результат, посчитанный при одинаковом количестве поездок, полезен внутри диапазона, где физические и договорные ограничения остаются прежними.",
        f"Допустим, в текущей схеме понадобится ещё одна поездка. Расход увеличится до {rub(next_cost)}. При {boxes} коробках альтернатива всё ещё стоит {rub(boxes*unit+fixed)}. Разница меняется на {rub(ticket)}. Если в этом случае отправки приходится переносить или отделять коробки другой категории, добавьте прямые затраты на оставшуюся часть и пересчитайте. Продавцу удобно по каждой неделе отмечать подтверждённое число отдельных рейсов, которые он действительно избежал. Когда альтернативный способ экономит только два выезда, сравнивать его со стоимостью всего старого графика некорректно.",
        f"Для итоговой проверки сведите счёт перевозчика, журнал передачи и допустимые окна приёма. Платёж {rub(fixed)} может зависеть от длительности договора. Если договор на месяц, а тест шёл неделю, в счёте показывайте оба варианта: подтверждённый месячный расход и ожидаемую экономику стабильного объёма. Закрепите, что считаете переданной коробкой, если её пришлось отправлять повторно. При задержанных заказах проверьте день фактической передачи. Тогда цифра о цене перевозки останется проверяемой даже при изменении маршрута, объёма или требований к точке приёма."
    )


def recovery(v, action):
    qty, residual, cost, after, success=v
    delta=after-residual
    gain=delta*success/100-cost
    max_cost=delta*success/100
    need=ceil(qty*cost/delta)
    return (
        f"Прежде чем согласовать «{action}», полезно определить допустимую стоимость попытки. При доле успеха {success}% ожидаемое улучшение чистого поступления составляет {rub(max_cost,2)} на осмотренный объект. Отнимаем запланированные {rub(cost)} и получаем {rub(gain,2)}. Если цена материалов и повторной проверки больше допустимой границы, этот план уже не увеличивает ожидаемый денежный результат. Установите отдельную границу для объектов с повреждением, где чистое поступление в альтернативном варианте отличается. Не переносите цену удачного случая на все товары в коробке без проверки.",
        f"Возьмите один дополнительный подтверждённый успех в группе {qty}. Он повысит итог на {rub(delta)} при неизменном числе попыток и сохранении исходной стоимости остальных единиц. Если один из {need} нужных результатов не состоялся, расчётный порог не выполняется при прежней себестоимости работы. Эта чувствительность помогает выбрать размер пилота. На маленькой выборке успех часто зависит от качества целой партии. Сохраните результаты по источнику возврата и виду дефекта, чтобы постановка задачи отражала сравнимый товар. Если после ремонта меняется политика допустимого состояния, обновите возможный путь реализации.",
        f"В журнале полезно отразить, кто подтвердил исходную оценку {rub(residual)} и кто обновил её после осмотра. Для «{action}» сохраните статус разрешённого использования и дату, когда сделана попытка. Отдельным шагом подтвердите реальное поступление и расходы от продажи или передачи. Если товар оценивали по плановой цене, а потом предложили покупателю уценку, это движение внесите для соответствующей группы. Остаточную стоимость разукомплектованных товаров подтвердите способом, который действительно доступен магазину. Так в модели останутся только пригодные продажи и проверяемые данные."
    )


def experiment(v, event):
    n0,k0,n1,k1,gain=v
    r0,r1=k0/n0,k1/n1
    share=n1//2
    return (
        f"Для второй контрольной проверки возьмите общий объём, например {share} наблюдений. Исходное отношение даёт {fmt(share*r0,1)} заказанной единицы, после изменения {fmt(share*r1,1)}. Сравнение на одинаковой базе показывает отличие отношений, но не отменяет разные условия показа. В одной неделе товары видели покупатели с большей готовностью к покупке, в другой могла вырасти доля общей выдачи. Для рабочего эксперимента заранее назначьте дату старта, исходное предложение, допустимые источники и правило исключения недоступных дней. Если единица «{event}» считается только для всей карточки, не подставляйте её под продажи одного размера без подтверждённой связи.",
        f"Добавьте проверку денежного ориентира. Если вклад с доставленной единицы вместо {rub(gain)} снизится на четверть, условный эффект текущей разницы составит {rub((k1-n1*r0)*gain*.75)} при сохранении допущения о доставке. При росте вклада на четверть получится {rub((k1-n1*r0)*gain*1.25)}. Эта пара полезна, если одновременно поменялась упаковка или часть затрат на доставку. Если деньги фактически изменились, сравните чистую цену, себестоимость и услуги по зрелой группе. Для управленческого вывода лучше допустить, что влияние новой карточки на продажи ещё требует подтверждения.",
        f"При следующем замере «{event}» сохраните исходный фильтр вместе с датами и отсеките переходный день, когда была доступна старая версия. Что ещё можно проверить, кроме заказанных единиц? Откройте живое предложение и сопоставьте вопрос покупателей с тем, какую информацию добавили. Отдельно проследите сообщения о размере, совместимости или составе после доставки, если они относятся к этому тесту. Если несколько изменений запустили вместе, итог описывайте как результат их сочетания. На следующем цикле можно изменить только один элемент и продолжить сравнение на том же показателе."
    )


SUPPLEMENTS.update({"06":mix,"07":report,"08":route,"09":recovery,"10":experiment})
